+const ABSOLUTE_ZERO: Record<Temperature, number> = { C: -273.15, F: -459.67, K: 0 };
+
+function isTemperature(unit: string): unit is Temperature {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(unit);
+}
+
+function isKnown(unit: string): boolean {
+  return Object.hasOwn(LINEAR_UNITS, unit) || isTemperature(unit);
+}
+
+function toCelsius(value: number, unit: Temperature): number {
+  if (unit === "F") return ((value - 32) * 5) / 9;
+  if (unit === "K") return value - 273.15;
+  return value;
+}
